import java.util.*;

class Solution {
  public int maxBoxesInWarehouse(int[] boxes, int[] warehouse) {
    Arrays.sort(boxes);
    int left = 0, right = warehouse.length - 1, count = 0;
    // largest box first: put it at whichever open end it fits, otherwise drop it
    for (int b = boxes.length - 1; b >= 0 && left <= right; b--) {
      if (boxes[b] <= warehouse[left]) {
        left++;
        count++;
      } else if (boxes[b] <= warehouse[right]) {
        right--;
        count++;
      }
    }
    return count;
  }
}
